import { httpClient } from '@/shared/api/httpClient'
import type { AddCartItemRequest, CartResponse, UpdateCartItemRequest } from '../types/cart'

/** Cart identity travels in a header; the id is generated by the server (`POST /cart`). */
export const CART_ID_HEADER = 'X-Cart-Id'

const withCart = (cartId: string) => ({ headers: { [CART_ID_HEADER]: cartId } })

const itemPath = (variantId: string) => `/cart/items/${encodeURIComponent(variantId)}`

export async function createCart(): Promise<CartResponse> {
  const { data } = await httpClient.post<CartResponse>('/cart')
  return data
}

/** Rejects with ApiError 404 / CART_NOT_FOUND for unknown, malformed or expired ids. */
export async function getCart(cartId: string): Promise<CartResponse> {
  const { data } = await httpClient.get<CartResponse>('/cart', withCart(cartId))
  return data
}

/** Adding a variant already in the cart merges the quantities into the same line. */
export async function addCartItem(cartId: string, body: AddCartItemRequest): Promise<CartResponse> {
  const { data } = await httpClient.post<CartResponse>('/cart/items', body, withCart(cartId))
  return data
}

/** Sets the absolute quantity of a line. */
export async function updateCartItem(cartId: string, variantId: string, body: UpdateCartItemRequest): Promise<CartResponse> {
  const { data } = await httpClient.patch<CartResponse>(itemPath(variantId), body, withCart(cartId))
  return data
}

export async function removeCartItem(cartId: string, variantId: string): Promise<CartResponse> {
  const { data } = await httpClient.delete<CartResponse>(itemPath(variantId), withCart(cartId))
  return data
}
